const crypto = require('crypto');

const item = $input.first();
const reject = (message) => [{ json: { rejected: true, error_code: 'invalid_input', message } }];

const customerId = Number(item.json.customer_id);
if (!Number.isInteger(customerId) || customerId <= 0) {
  return reject('customer_id must be a positive integer');
}

const hasPdf = Boolean(item.binary && item.binary.data);
const hasLines = Array.isArray(item.json.lines) && item.json.lines.length > 0;
if (!hasPdf && !hasLines) {
  return reject('Provide either a PDF in binary field "data" or a non-empty "lines" array');
}

if (hasPdf) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buffer.subarray(0, 5).toString('latin1') !== '%PDF-') {
    return reject('The uploaded file is not a PDF');
  }
  return [{
    json: {
      customer_id: customerId,
      source_name: item.json.source_name || item.binary.data.fileName || 'rfq.pdf',
      source_sha256: crypto.createHash('sha256').update(buffer).digest('hex'),
      mode: 'pdf',
    },
    binary: { data: item.binary.data },
  }];
}

const lines = item.json.lines.map((l, i) => ({
  line_no: Number.isInteger(Number(l.line_no)) ? Number(l.line_no) : i + 1,
  code: l.code ? String(l.code).trim() : null,
  description: String(l.description ?? '').trim(),
  qty: l.qty === undefined || l.qty === null || l.qty === '' ? null : Number(String(l.qty).replace(',', '.')),
  unit: l.unit ? String(l.unit).trim() : null,
}));

return [{
  json: {
    customer_id: customerId,
    source_name: item.json.source_name || 'api-lines',
    source_sha256: crypto.createHash('sha256').update(JSON.stringify(lines)).digest('hex'),
    mode: 'lines',
    parser: 'api',
    lines,
  },
}];

const prep = $('Prepare input').first().json;
const text = String($input.first().json.text || '');
const rows = text.split(/\r?\n/).map((l) => l.replace(/\s+/g, ' ').trim()).filter(Boolean);

const UNIT = '(?:pcs|pc|kom|ea|each|x|m|mtr|mtrs|meters?|metres?|lm|rolls?|rings?|coils?|reels?|packs?|pk|pkg|box(?:es)?|sets?|nos)';
const TABLE_ROW = new RegExp(`^(\\d{1,3})\\s+(.+?)\\s+(\\d+(?:[.,]\\d+)?)\\s+(${UNIT})\\.?$`, 'i');
const BULLET_ROW = new RegExp(`^(?:[-\\u2022*\\u2013]|\\d{1,3}[.)])\\s*(\\d+(?:[.,]\\d+)?)\\s*(${UNIT})?\\b\\.?\\s*(.+)$`, 'i');
const HEADER_WORDS = ['pos', 'item', 'code', 'description', 'qty', 'quantity', 'unit', 'uom', 'article'];

const toNumber = (s) => Number(String(s).replace(',', '.'));
const looksLikeCode = (token) => (token.match(/\d/g) || []).length >= 3
  && token.length >= 5
  && /^[A-Za-z0-9][A-Za-z0-9._/-]*$/.test(token);

function parseTable() {
  const headerAt = rows.findIndex((l) => {
    const words = l.toLowerCase().split(/[^a-z]+/);
    return HEADER_WORDS.filter((w) => words.includes(w)).length >= 3;
  });
  if (headerAt < 0) return null;

  const lines = [];
  const unparsed = [];
  for (const row of rows.slice(headerAt + 1)) {
    const m = row.match(TABLE_ROW);
    if (m) {
      const [, pos, middle, qty, unit] = m;
      const first = middle.split(' ')[0];
      const code = looksLikeCode(first) ? first : null;
      lines.push({
        line_no: Number(pos),
        code,
        description: code ? middle.slice(first.length).trim() : middle,
        qty: toNumber(qty),
        unit,
      });
    } else if (/^\d{1,3}\s+\S/.test(row)) {
      unparsed.push(row);
    }
  }
  return lines.length ? { parser: 'table', lines, unparsed } : null;
}

function parseList() {
  const lines = [];
  for (const row of rows) {
    const m = row.match(BULLET_ROW);
    if (m) {
      lines.push({ line_no: lines.length + 1, code: null, description: m[3].trim(), qty: toNumber(m[1]), unit: m[2] || null });
    }
  }
  return lines.length ? { parser: 'list', lines, unparsed: [] } : null;
}

const result = parseTable() || parseList() || { parser: 'none', lines: [], unparsed: [] };

let next = result.lines.reduce((max, l) => Math.max(max, l.line_no), 0) + 1;
for (const row of result.unparsed) {
  result.lines.push({ line_no: next++, code: null, description: row, qty: null, unit: null });
}

return [{
  json: {
    ...prep,
    parser: result.parser,
    lines: result.lines,
    unparsed_count: result.unparsed.length,
    source_text: text.slice(0, 20000),
  },
}];

const prep = $input.first().json;

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['lines'],
  properties: {
    lines: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['code', 'description', 'qty', 'unit'],
        properties: {
          code: { type: ['string', 'null'], description: 'Item or part code exactly as written, or null' },
          description: { type: 'string', description: 'Product description copied from the text, not rewritten' },
          qty: { type: ['number', 'null'], description: 'Requested quantity as a number, words converted to digits' },
          unit: { type: ['string', 'null'], description: 'Unit as written (m, pcs, roll...), or null' },
        },
      },
    },
  },
};

const system = [
  'You extract requested line items from a customer request for quotation.',
  'Only extract products the customer asks to be quoted. Ignore greetings, delivery notes and questions.',
  'Copy product descriptions as written. Do not correct, complete or translate them.',
  'Convert quantities written as words to digits. Use null when a code, quantity or unit is not stated.',
  'Never invent items that are not in the text.',
].join(' ');

return [{
  json: {
    ...prep,
    llm_request: {
      model: $env.LLM_MODEL || 'gpt-4.1-mini',
      temperature: 0,
      response_format: { type: 'json_schema', json_schema: { name: 'rfq_lines', strict: true, schema } },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: prep.source_text },
      ],
    },
  },
}];

const prep = $('Build LLM request').first().json;
const response = $input.first().json;

let parsed;
try {
  parsed = JSON.parse(response.choices?.[0]?.message?.content ?? '');
} catch (e) {
  throw new Error('The LLM did not return valid JSON for the RFQ lines');
}

const source = prep.source_text.toLowerCase().replace(/(\d),(\d)/g, '$1.$2');
const tokens = (s) => String(s).toLowerCase().replace(/(\d),(\d)/g, '$1.$2').split(/[^a-z0-9.]+/).filter((t) => t.length >= 2);

const lines = [];
const rejected = [];
for (const l of parsed.lines || []) {
  const description = String(l.description || '').trim();
  const words = tokens(description);
  const grounded = words.length > 0 && words.filter((w) => source.includes(w)).length / words.length >= 0.6;
  if (!description || !grounded) {
    rejected.push({ description, reason: description ? 'NOT_FOUND_IN_SOURCE' : 'EMPTY_DESCRIPTION' });
    continue;
  }
  const qty = Number(l.qty);
  lines.push({
    line_no: lines.length + 1,
    code: l.code ? String(l.code).trim() : null,
    description,
    qty: Number.isFinite(qty) && qty > 0 ? qty : null,
    unit: l.unit ? String(l.unit).trim() : null,
  });
}

for (const r of rejected) {
  lines.push({ line_no: lines.length + 1, code: null, description: `[unverified LLM output] ${r.description}`.trim(), qty: null, unit: null });
}

return [{
  json: {
    customer_id: prep.customer_id,
    source_name: prep.source_name,
    source_sha256: prep.source_sha256,
    mode: prep.mode,
    parser: 'llm',
    lines,
    llm_model: response.model || null,
    llm_rejected: rejected.length,
  },
}];
